SELECT CAST(j.did AS VARCHAR) AS user_id, CAST((MAX(CAST(j.time_us AS BIGINT)) - MIN(CAST(j.time_us AS BIGINT))) / 1000 AS BIGINT) AS activity_span_ms FROM bluesky WHERE CAST(j.kind AS VARCHAR) = 'commit' AND CAST(j.commit.operation AS VARCHAR) = 'create' AND CAST(j.commit.collection AS VARCHAR) = 'app.bsky.feed.post' GROUP BY user_id ORDER BY activity_span_ms DESC, user_id LIMIT 3;
